//! Comparator (ACMP) pad functions of the SWM341 pin matrix.
//!
//! Generated by `scripts/gen_pin_func.py` from the vendor header
//! `SWM341_port.h` -- do not edit by hand.
//!
//! Each `Pin{n}Func` enumerates the comparator functions selectable on pin `{n}`
//! of its bank; the numeric value of every variant is the 4-bit code written
//! into `PORTx.FUNC0/FUNC1` (always `15`, the analog path). `ACMPx_INP` is the
//! positive (non-inverting) input of comparator `x`, `ACMPx_INN` its negative
//! (inverting) input. Code `0` (generic GPIO) is omitted. The variants are the
//! type-checked arguments to [`crate::cmp::Cmp::add_positive_pin`] /
//! [`crate::cmp::Cmp::add_negative_pin`].


/// Generate the per-pin `Pin{n}Func` enums for one bank module.
///
/// Each entry is `PinType => Enum { Variant = func_code, ... }`; the macro
/// writes the `#[repr(u8)]` enum plus its `PinFunc` / `PinFuncOf` impls.
macro_rules! pad_funcs {
    ( $( $pin_ty:ident => $enum:ident { $( $var:ident = $val:literal ),* $(,)? } ),* $(,)? ) => {
        $(
            #[derive(Clone, Copy, PartialEq, Eq, Debug)]
            #[repr(u8)]
            pub enum $enum {
                $( $var = $val ),*
            }
            impl crate::gpio::PinFunc for $enum {
                #[inline]
                fn value(self) -> u8 { self as u8 }
            }
            impl crate::gpio::PinFuncOf<crate::gpio::$pin_ty> for $enum {}
        )*
    };
}

pub mod a {
    pad_funcs! {
        PA0 => Pin0Func { Acmp2Inp = 15 },
        PA1 => Pin1Func { Acmp1Inp = 15 },
        PA2 => Pin2Func { Acmp0Inp = 15 },
    }
}

pub mod b {
    pad_funcs! {
        PB4 => Pin4Func { Acmp2Inn = 15 },
        PB5 => Pin5Func { Acmp1Inn = 15 },
        PB12 => Pin12Func { Acmp0Inn = 15 },
    }
}
